{
  "interpretation": {
    "name": "Line2NutrunnerTightening",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, then return the tool to the crib and release it for line 3.",
    "constraints": [
      "NR7 must be reserved before any tool-using Step, and the reservation token must be used for every tool-using Step (lease renewal).",
      "transport-tool must be executed by agvexecutor.",
      "NR7 must be at st2 before configure-tool and tighten-fasteners.",
      "The tightening program comes only from get-program, with no literal values in the Recipe.",
      "The tightening must be evaluated and recorded.",
      "NR7 must be released after it is back at the crib."
    ],
    "preference": "Minimize the time NR7 is away from the crib, because line 3 is waiting. Get the program before transport, return the tool right after tightening, and run evaluation and recording in parallel with the return transport.",
    "priority": "normal",
    "horizon": "Single execution, starting now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nutrunner-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-f30-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return-and-close",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["reserve-nr7", "get-f30-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["reserve-nr7", "configure-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-close",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate-result",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "get-f30-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-result",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
